import{_ as c,C as l,o as i,c as p,a2 as t,b as r,w as e,a as d,E as n,a3 as s}from"./chunks/framework.DZUUNQ77.js";const v=JSON.parse('{"title":"应用虚拟化","description":"","frontmatter":{},"headers":[],"relativePath":"features/app-virtualization.md","filePath":"features/app-virtualization.md","lastUpdated":1784494692000}'),E={name:"features/app-virtualization.md"};function A(h,a,k,g,B,u){const o=l("Mermaid");return i(),p("div",null,[a[2]||(a[2]=t('<h1 id="应用虚拟化" tabindex="-1">应用虚拟化 <a class="header-anchor" href="#应用虚拟化" aria-label="Permalink to &quot;应用虚拟化&quot;">​</a></h1><p>“应用虚拟化”是 VirtualApp 的核心能力——<strong>让一个没有装进系统的 App，能在 VirtualXposed 的进程里跑起来，并且以为自己在真系统里</strong>。这一篇讲这个目标是怎么达成的，串联起后续各篇。</p><h2 id="目标分解" tabindex="-1">目标分解 <a class="header-anchor" href="#目标分解" aria-label="Permalink to &quot;目标分解&quot;">​</a></h2><p>要把一个 App“虚拟化”地跑起来，要解决这些问题：</p><ol><li><strong>安装</strong>：不调用系统 PMS，自己解析 APK、复制文件、记录包信息。</li><li><strong>启动</strong>：不靠系统 PMS 拉起进程，自己调度进程并绑定 Application。</li><li><strong>运行时欺骗</strong>：App 调系统服务（定位、电话、账户……）时，返回虚拟数据而非真系统数据。</li><li><strong>数据隔离</strong>：App 的 <code>/data/data/&lt;pkg&gt;</code> 要独立，不能写到宿主真实数据目录。</li><li><strong>组件调度</strong>：App 的 Activity/Service/Receiver 启动要走 VirtualXposed 自己的 AMS，而非系统 AMS。</li></ol><p>每一项对应一个机制：</p><table tabindex="0"><thead><tr><th>问题</th><th>机制</th><th>详解篇</th></tr></thead><tbody><tr><td>安装</td><td><code>VAppManagerService</code> + <code>VPackageManagerService</code></td><td><a href="./package-manager">包管理</a></td></tr><tr><td>启动 + 组件调度</td><td><code>VActivityManagerService</code> + Stub Activity</td><td><a href="./activity-manager">活动管理</a>、<a href="./stub-activity">Stub Activity</a></td></tr><tr><td>运行时欺骗</td><td><code>InvocationStubManager</code> + 各服务代理</td><td><a href="./service-hook">系统服务 Hook</a></td></tr><tr><td>数据隔离</td><td><code>NativeEngine</code> IO 重定向</td><td><a href="./io-redirect">IO 重定向</a></td></tr><tr><td>跨进程通信</td><td><code>BinderProvider</code> + <code>ServiceManagerNative</code></td><td><a href="./ipc-bridge">IPC 桥</a></td></tr></tbody></table><p>这五块的关系：</p>',8)),(i(),r(s,null,{default:e(()=>[n(o,{id:"mermaid-117",class:"mermaid",graph:"flowchart%20LR%0A%20%20INSTALL%5B%22%E5%AE%89%E8%A3%85%3Cbr%2F%3EVAppManagerService%22%5D%0A%20%20SCHED%5B%22%E5%90%AF%E5%8A%A8%2B%E8%B0%83%E5%BA%A6%3Cbr%2F%3EVActivityManagerService%3Cbr%2F%3E%2B%20Stub%20Activity%22%5D%0A%20%20HOOK%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E6%AC%BA%E9%AA%97%3Cbr%2F%3EInvocationStubManager%3Cbr%2F%3E%2B%2060%E4%B8%AA%E6%9C%8D%E5%8A%A1%E4%BB%A3%E7%90%86%22%5D%0A%20%20IO%5B%22%E6%95%B0%E6%8D%AE%E9%9A%94%E7%A6%BB%3Cbr%2F%3ENativeEngine%3Cbr%2F%3EIO%20%E9%87%8D%E5%AE%9A%E5%90%91%22%5D%0A%20%20IPC%5B%22%E8%B7%A8%E8%BF%9B%E7%A8%8B%E9%80%9A%E4%BF%A1%3Cbr%2F%3EBinderProvider%3Cbr%2F%3E%2B%20ServiceManagerNative%22%5D%0A%20%20INSTALL%20--%3E%20SCHED%0A%20%20SCHED%20--%3E%20HOOK%0A%20%20IPC%20-.%20%E6%9C%8D%E5%8A%A1%E6%80%BB%E7%BA%BF%20.-%3E%20INSTALL%0A%20%20IPC%20-.%20%E6%9C%8D%E5%8A%A1%E6%80%BB%E7%BA%BF%20.-%3E%20SCHED%0A%20%20IPC%20-.%20%E6%9C%8D%E5%8A%A1%E6%80%BB%E7%BA%BF%20.-%3E%20HOOK%0A%20%20IO%20-.%20%E6%B2%99%E7%AE%B1%20.-%3E%20HOOK%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t(`<p>这一篇只讲总流程，把上面几个机制串起来。</p><h2 id="安装-把-apk-纳入虚拟管理" tabindex="-1">安装：把 APK 纳入虚拟管理 <a class="header-anchor" href="#安装-把-apk-纳入虚拟管理" aria-label="Permalink to &quot;安装：把 APK 纳入虚拟管理&quot;">​</a></h2><p>用户在 VirtualXposed 里“添加应用”时，<code>VirtualCore.installPackage(apkPath, flags)</code> → 跨进程到 server 的 <code>VAppManagerService.installPackage()</code>：</p><ol><li>解析 APK 的 <code>AndroidManifest.xml</code>（<code>PackageParser</code>），拿到包名、组件、权限等。</li><li>把 APK 复制到 VirtualXposed 私有目录下的虚拟安装区（<code>VEnvironment</code> 管理的路径）。</li><li>在 <code>PackageCacheManager</code> 里登记这个包的 <code>PackageSetting</code>。</li><li>（可选）多用户安装：<code>installPackageAsUser(userId, pkg)</code>。</li></ol><p>注意：<strong>系统 PMS 完全不知道这个 App 存在</strong>。它只存在于 VirtualXposed 自己的包数据库里。详见<a href="./package-manager">包管理</a>。</p><h2 id="启动-拉起虚拟进程并绑定-application" tabindex="-1">启动：拉起虚拟进程并绑定 Application <a class="header-anchor" href="#启动-拉起虚拟进程并绑定-application" aria-label="Permalink to &quot;启动：拉起虚拟进程并绑定 Application&quot;">​</a></h2><p>用户点桌面图标，主进程调 <code>VirtualCore.launchApp()</code>，最终走到 server 的 <code>VActivityManagerService.startActivity()</code>：</p><ol><li>server 查 <code>VPackageManager</code> 找到目标 Activity 信息。</li><li>server 通过<strong>真实 AMS</strong> 启动一个宿主子进程（用预注册的 Stub Activity 作为进程入口，绕过“App 没装系统”的限制）。</li><li>新进程起来，<code>VirtualCore.startup()</code> 判定自己是 <code>VAppClient</code>，注入全套 Hook。</li><li><code>HCallbackStub</code> 拦截 <code>LAUNCH_ACTIVITY</code>，发现真实 Intent，调 <code>VClientImpl.bindApplicationForActivity()</code>。</li><li><code>VClientImpl.bindApplicationNoCheck()</code> 做核心绑定： <ul><li>拿目标 App 的 <code>ApplicationInfo</code>（从 <code>VPackageManager</code>，不是系统 PMS）。</li><li><code>createPackageContext</code> 构造一个加载了目标 App 代码的 ClassLoader。</li><li><strong>IO 重定向</strong>：把 <code>/data/data/&lt;pkg&gt;</code> 重定向到虚拟数据目录（<code>startIOUniformer</code>）。</li><li><strong>加载 Xposed</strong>：<code>ExposedBridge.initOnce</code> + 遍历模块 <code>loadModule</code>（如果启用）。</li><li><code>LoadedApk.makeApplication</code> 创建目标 App 的 <code>Application</code> 实例。</li><li><code>installContentProviders</code> 安装目标 App 声明的 ContentProvider。</li><li><code>callApplicationOnCreate</code> —— 目标 App 的 <code>Application.onCreate()</code> 执行。</li></ul></li></ol><p>从此这个进程“就是”目标 App 了，目标 App 的代码在跑，并且（若启用）Xposed 模块的 Hook 已经挂上。详见<a href="./activity-manager">活动管理</a>和<a href="./../xposed/how-it-works">Xposed 集成</a>。</p><h2 id="运行时-拦截每一个系统调用" tabindex="-1">运行时：拦截每一个系统调用 <a class="header-anchor" href="#运行时-拦截每一个系统调用" aria-label="Permalink to &quot;运行时：拦截每一个系统调用&quot;">​</a></h2><p>目标 App 跑起来后会大量调用系统服务：<code>getDeviceId()</code>、<code>getLocation()</code>、<code>getAccounts()</code>…… 这些调用都经过 <code>InvocationStubManager</code> 注入的代理：</p><ul><li>目标 App <code>getSystemService(LOCATION_SERVICE)</code> → 拿到的是 <code>LocationManagerStub</code> 注入的代理。</li><li>代理上的 <code>getLastLocation</code> 方法被 <code>MethodProxy</code> 拦截 → 返回 <code>VirtualLocationService</code> 里的伪造坐标。</li><li>真实系统的定位完全不被触碰。</li></ul><p>近 60 个系统服务都被这样代理（见 <code>InvocationStubManager.injectInternal()</code> 列表）。每个代理是一个继承 <code>MethodInvocationProxy</code> 的 <code>*Stub</code> 类，内部用 <code>@Inject</code> 注解扫描内部类批量注册 <code>MethodProxy</code>。详见<a href="./service-hook">系统服务 Hook</a>。</p><h2 id="数据隔离-native-层路径重定向" tabindex="-1">数据隔离：native 层路径重定向 <a class="header-anchor" href="#数据隔离-native-层路径重定向" aria-label="Permalink to &quot;数据隔离：native 层路径重定向&quot;">​</a></h2><p>目标 App 写文件时，比如 <code>openFileOutput(&quot;x&quot;, MODE_PRIVATE)</code> 最终落到 <code>/data/data/&lt;目标pkg&gt;/files/x</code>。但这个目录在系统里不存在（App 没装系统），必须重定向到 VirtualXposed 私有目录下的虚拟数据区。</p><p>Java 层拦不住所有路径（很多 App 直接 native 读写），所以在 native 层 hook libc 的 <code>open</code>/<code>stat</code>/<code>readlink</code> 等，做透明路径替换：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// VClientImpl.startIOUniformer()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NativeEngine.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redirectDirectory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/data/data/&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> info.packageName, info.dataDir);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NativeEngine.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redirectDirectory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/data/user/0/&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> info.packageName, info.dataDir);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NativeEngine.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redirectDirectory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/sdcard&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, vsPath);  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 虚拟存储</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NativeEngine.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">enableIORedirect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>于是目标 App 看到的 <code>/data/data/&lt;自己&gt;</code> 实际是 VirtualXposed 里的隔离目录，多个虚拟 App 互不干扰，和宿主也隔离。详见<a href="./io-redirect">IO 重定向</a>。</p><h2 id="一张图串联" tabindex="-1">一张图串联 <a class="header-anchor" href="#一张图串联" aria-label="Permalink to &quot;一张图串联&quot;">​</a></h2>`,19)),(i(),r(s,null,{default:e(()=>[n(o,{id:"mermaid-267",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%94%A8%E6%88%B7%E7%82%B9%E5%9B%BE%E6%A0%87%22%5D%20--%3E%20B%5B%22%E4%B8%BB%E8%BF%9B%E7%A8%8B%20VirtualCore.launchApp%22%5D%0A%20%20B%20--%3E%7C%22IPC%22%7C%20C%5B%22server%20VActivityManagerService.startActivity%22%5D%0A%20%20C%20--%3E%7C%22%E7%94%A8%E7%9C%9F%E5%AE%9E%20AMS%20%E5%90%AF%E5%8A%A8%20Stub%20Activity%3Cbr%2F%3E%E6%8B%89%E6%96%B0%E8%BF%9B%E7%A8%8B%22%7C%20D%5B%22%E6%96%B0%E8%BF%9B%E7%A8%8B%20VirtualCore.startup%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%88%A4%E5%AE%9A%20VAppClient%3Cbr%2F%3E%E6%B3%A8%E5%85%A5%E5%85%A8%E5%A5%97%20Hook%22%5D%0A%20%20E%20--%3E%20F%5B%22HCallbackStub%20%E6%8B%A6%E6%88%AA%20LAUNCH_ACTIVITY%3Cbr%2F%3E%E2%86%92%20bindApplication%22%5D%0A%20%20F%20--%3E%20G1%5B%22createPackageContext%3Cbr%2F%3E(%E5%8A%A0%E8%BD%BD%E7%9B%AE%E6%A0%87%20App%20%E4%BB%A3%E7%A0%81)%22%5D%0A%20%20F%20--%3E%20G2%5B%22startIOUniformer%3Cbr%2F%3E(IO%20%E9%87%8D%E5%AE%9A%E5%90%91)%22%5D%0A%20%20F%20--%3E%20G3%5B%22ExposedBridge.initOnce%20%2B%20loadModule%3Cbr%2F%3E(Xposed)%22%5D%0A%20%20F%20--%3E%20G4%5B%22makeApplication%3Cbr%2F%3E(%E7%9B%AE%E6%A0%87%20App%20Application)%22%5D%0A%20%20G4%20--%3E%20H%5B%22callApplicationOnCreate%22%5D%0A%20%20H%20--%3E%20I%5B%22%E7%9B%AE%E6%A0%87%20App%20%E8%BF%90%E8%A1%8C%22%5D%0A%20%20I%20--%3E%7C%22%E8%B0%83%E7%B3%BB%E7%BB%9F%E6%9C%8D%E5%8A%A1%22%7C%20J%5B%22%E5%90%84%20*Stub%20%E4%BB%A3%E7%90%86%E6%8B%A6%E6%88%AA%3Cbr%2F%3E%E2%86%92%20%E8%BF%94%E5%9B%9E%E8%99%9A%E6%8B%9F%E6%95%B0%E6%8D%AE%20%2F%20%E8%BD%AC%E5%8F%91%E5%88%B0%20server%20%E8%99%9A%E6%8B%9F%E6%9C%8D%E5%8A%A1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[d(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>应用虚拟化 = <strong>自管安装 + 自管调度 + 全链路 Hook + native IO 重定向</strong>。VirtualApp 把这四件事都做透了，VirtualXposed 在此基础上加了第五件——在虚拟进程里加载 Xposed。</p><p>接下来按机制逐个钻进去，建议顺序：<a href="./service-hook">系统服务 Hook</a> → <a href="./stub-activity">Stub Activity</a> → <a href="./ipc-bridge">IPC 桥</a> → <a href="./package-manager">包管理</a> → <a href="./activity-manager">活动管理</a>。</p>',3))])}const b=c(E,[["render",A]]);export{v as __pageData,b as default};
